        Chapter(
            "benefits",
            "📈 Benefits Realisation & Value Metrics",
            "Value Chain · Benefits Register · VSM · OKRs · WSJF · Leading Indicators",
            "Business & tailoring",
            listOf(
                s("Key", "The 2026 ECO and PMBOK 8 move project success from \"on time, on budget, in scope\" to \"delivered value and realised benefits.\" This section covers how value is defined, measured, and tracked — a Business Environment (26%) core topic.", SectionKind.KEY),
                s("Beyond the Triple Constraint", tableHeaders = listOf("Traditional Metric", "Limitation", "Value-Based Alternative"), tableRows = listOf(listOf("Schedule variance", "Says nothing about whether the output matters", "Time-to-value; benefit realisation date"), listOf("Cost variance", "Under budget on a worthless deliverable is still failure", "ROI; NPV; cost per unit of value delivered"), listOf("Scope completion", "100% scope of the wrong thing", "Outcome achievement; adoption rate; customer satisfaction"), listOf("Quality (defects)", "Zero defects in an unused product", "Fitness for use; NPS; support ticket reduction"))),
                s("Value Delivery Chain", "Inputs→Activities→Outputs→Outcomes→Benefits→Value"),
                s("Value Delivery Chain", tableHeaders = listOf("Level", "Definition", "Example (Customer Portal Project)", "Who Measures"), tableRows = listOf(listOf("Outputs", "What the project produces", "Portal deployed; 40 features live", "Project team"), listOf("Outcomes", "Changes that outputs enable", "60% of customers use self-service instead of calling", "Project team + operations"), listOf("Benefits", "Measurable gains from outcomes", "Call centre costs down 35%; CSAT up 12 points", "Benefits owner (business)"), listOf("Value", "Net worth to the organisation and stakeholders", "\$2.4M annual savings; improved brand reputation", "Sponsor / portfolio"))),
                s("Benefits Register", "Companion to the Benefits Management Plan — tracks each benefit through its lifecycle:"),
                s("Benefits Register", tableHeaders = listOf("Field", "Content"), tableRows = listOf(listOf("Benefit ID & Name", "B-01: Reduced call centre volume"), listOf("Type", "Tangible / Intangible; Financial / Non-financial"), listOf("Baseline", "Current state measurement before the project (e.g., 50,000 calls/month)"), listOf("Target", "Expected future state (e.g., 32,500 calls/month — 35% reduction)"), listOf("Metric & Measurement Method", "Monthly call volume from ACD system"), listOf("Timeframe", "Realisation begins Month 3 post-launch; full realisation Month 9"), listOf("Owner", "Head of Customer Operations (NOT the PM — benefits outlive the project)"), listOf("Dependencies", "Marketing campaign to drive portal adoption; staff retraining"), listOf("Status", "Planned / In Progress / Realised / At Risk / Not Realised"), listOf("Disbenefits", "Potential negative consequences — e.g., 15 call centre roles eliminated"))),
                s("Value Stream Mapping", "A Lean technique that visualises every step from request to delivered value, exposing waste and delay:"),
                s("Value Stream Mapping", tableHeaders = listOf("Element", "Definition"), tableRows = listOf(listOf("Value-Added Time (VA)", "Time spent on activities the customer would pay for"), listOf("Non-Value-Added Time (NVA)", "Waiting, handoffs, rework, approvals that add no customer value"), listOf("Lead Time", "Total elapsed time from request to delivery (VA + NVA)"), listOf("Process Cycle Efficiency (PCE)", "VA Time ÷ Lead Time × 100%"), listOf("Current State Map", "How value flows today — usually reveals PCE of 5–15%"), listOf("Future State Map", "Redesigned flow with waste removed"))),
                s("Value Stream Mapping", "Process Cycle Efficiency"),
                s("OKRs — Objectives and Key Results", "A goal-setting framework increasingly used to link projects to strategic outcomes. Structure: one qualitative Objective, 2–5 measurable Key Results."),
                s("Worked example — OKRs — Objectives and Key Results", "Objective: Make self-service the preferred support channel\n\nKR1: Increase portal monthly active users from 12,000 to 45,000\n\nKR2: Reduce call centre volume by 35%\n\nKR3: Achieve portal CSAT score of 4.3/5 or higher\n\nKR4: Cut average issue resolution time from 48h to 8h\n\nHow the project links: The Customer Portal project delivers the OUTPUTS; the OKRs measure whether OUTCOMES are achieved. A project can hit 100% scope and 0% OKRs — that is a failed project by PMBOK 8 standards.", SectionKind.TIP),
                s("OKRs — Objectives and Key Results", tableHeaders = listOf("OKR Principle", "Application"), tableRows = listOf(listOf("Ambitious", "Key results should be stretch targets — 70% achievement is considered success"), listOf("Measurable", "Every KR has a number; no \"improve\" or \"enhance\" without a metric"), listOf("Time-bound", "Typically quarterly; reviewed and re-set"), listOf("Transparent", "Visible across the organisation; aligned top-down and bottom-up"), listOf("Outcome-focused", "KRs measure results, not activities (\"reduce churn 10%\" not \"launch retention campaign\")"))),
                s("Value Metrics Toolkit", tableHeaders = listOf("Metric", "Formula / Definition", "Use"), tableRows = listOf(listOf("NPV", "Σ (Cash Flowt ÷ (1+r)t) − Initial Investment", "Project selection; accounts for time value of money"), listOf("ROI", "(Net Benefit − Cost) ÷ Cost × 100%", "Simple return comparison"), listOf("Payback Period", "Time until cumulative benefits = cumulative costs", "Cash-flow risk; shorter = less risk"), listOf("BCR", "PV Benefits ÷ PV Costs", ">1 = viable"), listOf("Time-to-Value", "Elapsed time from project start to first realised benefit", "Agile/incremental delivery justification"), listOf("Net Promoter Score (NPS)", "% Promoters − % Detractors", "Customer value perception"), listOf("Adoption Rate", "Users actively using ÷ Target users × 100%", "Whether outputs became outcomes"), listOf("Cost of Delay (CoD)", "Value lost per unit time of delay", "Prioritisation (WSJF = CoD ÷ Job Size)"), listOf("Customer Lifetime Value (CLV)", "Revenue per customer × retention period", "Product/feature value"), listOf("Total Cost of Ownership (TCO)", "Acquisition + Operation + Maintenance + Disposal", "True cost comparison across options"))),
                s("Benefits Realisation Roles", tableHeaders = listOf("Role", "Responsibility"), tableRows = listOf(listOf("Sponsor", "Accountable for the business case and overall benefits; approves Benefits Management Plan"), listOf("Benefits Owner", "Business-side individual accountable for realising and reporting a specific benefit — usually operations, not the PM"), listOf("Project Manager", "Ensures outputs enable outcomes; tracks leading indicators during the project; hands over with benefits tracking in place"), listOf("PMO / Portfolio", "Aggregates benefits across projects; validates strategic contribution; audits realisation"), listOf("Operations", "Sustains the change; measures and reports realised benefits post-project"))),
                s("Benefits Realisation Roles", "Exam trap: \"Who is accountable for benefits realisation after the project closes?\" → NOT the PM. It is the Benefits Owner / Sponsor / Operations. The PM's accountability ends at handover with tracking mechanisms in place.", SectionKind.WARN),
                s("Leading vs. Lagging Value Indicators", "Leading Indicators (predict future value)\n • Pilot user adoption rate\n• Early customer feedback / NPS on increments\n• Feature usage analytics during beta\n• Stakeholder engagement level\n• Sprint velocity trend\n• Defect escape rate\nLagging Indicators (confirm value delivered)\n • Revenue increase\n• Cost reduction realised\n• Market share change\n• Customer retention rate\n• Regulatory compliance achieved\n• Annual ROI"),
                s("Leading vs. Lagging Value Indicators", "Track LEADING indicators during the project so you can course-correct. Wait for LAGGING indicators only and you find out too late.", SectionKind.TIP),
                s("Worked example — Value Stream Mapping — Real Fintech Example", "Current State: Loan Application Processing\n\nCustomer submits loan application → Credit team receives it (next day) → Manual document verification (3 days) → CIBIL check (2 hours, but waits 1 day in queue) → Credit analysis (2 days) → Manager approval (waits 2 days) → Offer letter generated (same day) → Customer receives offer (3 days by post)\n\nTotal Lead Time: ~13 days\n\nValue-Added Time: ~2.5 days (actual analysis, verification, offer generation)\n\nNon-Value-Added (Waste): ~10.5 days (waiting between steps, queue time, postal delay)\n\nPCE: 2.5/13 = 19.2%\n\nWaste identified:\n\n• T — Transport: Documents physically moved between departments (2 days)\n\n• W — Waiting: Documents sit in queue for 4–5 days total\n\n• O — Overproduction: Printing 12-page applications (most never read fully)\n\n• D — Defects: 15% of applications have missing documents → returned → 3 more days\n\nFuture State (after digital transformation project):\n\nCustomer submits digitally → Auto-document extraction (AI, 10 min) → CIBIL check real-time (2 min) → AI credit analysis (30 min) → Manager approval (same day) → Offer letter emailed (instant)\n\nNew Lead Time: ~1 day\n\nPCE: ~0.8 days / 1 day = 80%\n\nThe digital project's value: 12 days of waste eliminated per application × 500 applications/month = 6,000 days of customer wait time saved monthly. Customer NPS expected to improve from 34 to 62.", SectionKind.TIP),
                s("Worked example — OKRs Linked to Project Outcomes — Complete Example", "Organisation Strategic Goal: Become the #1 digital bank for SMEs in India by 2027\n\nQ3 OKR at Portfolio Level:\n\nObjective: Make SME banking fully paperless\n\nKR1: 80% of new SME account openings completed digitally (baseline: 12%)\n\nKR2: Average account opening time reduced from 8 days to same-day\n\nKR3: Document rejection rate reduced from 28% to Project OKRs (how this project contributes):\n\nProject: \"AI-powered document verification system\"\n\nObjective: Eliminate manual document review from SME onboarding\n\nKR1: AI correctly classifies 95% of submitted documents (validated in UAT)\n\nKR2: Average document verification time reduced from 3 days to 4 minutes\n\nKR3: False rejection rate Leading indicators tracked DURING the project:\n\n• Pilot with 50 applications: AI accuracy rate 91% (below 95% target — retrain model)\n\n• Pilot verification time: 6 minutes (above 4-minute target — optimize pipeline)\n\n→ Both issues caught in PILOT before full rollout. Retrained model reaches 96%. Pipeline optimized to 3.5 minutes.\n\nLagging indicators tracked AFTER project closes:\n\n• 3 months post-launch: digital account opening rate: 67% (target 80% — needs marketing push)\n\n• Account opening time: 4 hours (target: same-day — still has manual approval step to remove)\n\n→ Benefits owner (Head of Digital Banking) drives the remaining gap through operational changes.", SectionKind.TIP),
                s("Worked example — AI in Project Management — Practical PM Workflow", "How a PM might use AI responsibly in a week:\n\nMonday — Risk Identification:\n\nPM prompts AI: \"Here is our project description and current risk register [anonymised, no confidential data]. What additional risks might we be missing for a fintech project with these characteristics?\"\n\nAI suggests 8 additional risks including \"quantum computing threat to current encryption standards.\"\n\n→ PM reviews each. Accepts 5 as valid; rejects 3 as irrelevant. Adds accepted risks to register. VALIDATES with tech lead before finalising.\n\n→ Disclosure: Risk register notes \"Initial identification assisted by AI; all risks validated by PM and tech lead.\"\n\nWednesday — Status Report Drafting:\n\nPM feeds AI the week's WPD (story points, cost data, blockers — no personal data).\n\nAI drafts a 200-word executive summary in the format requested.\n\n→ PM reviews, corrects two facts the AI hallucinated (it invented a meeting outcome), adds context the AI lacked, personalises the tone.\n\n→ Sends the report under PM's name. Discloses in team meeting that AI drafting is part of the workflow.\n\nThursday — Schedule Risk Analysis:\n\nAI runs Monte Carlo simulation on the schedule (10,000 iterations) in 30 seconds — a task that would take a human with Crystal Ball 2 hours.\n\nOutput: \"87% probability of completing by 15 March; 95% by 28 March.\"\n\n→ PM uses the 95% date (28 March) for the sponsor commitment. Documents the analysis method in the project file.\n\n→ What the PM does NOT do: commit to the 87% date as a firm deadline without buffer.\n\nWhat the PM does NOT use AI for:\n\n• Mediating the conflict between two team members (requires EI, relationship, nuance)\n\n• Making the final go/no-go decision on the risk response (PM is accountable)\n\n• Handling the emotionally charged conversation with the sponsor about the delay\n\n• Any analysis requiring confidential client data fed into an unapproved external tool", SectionKind.TIP),
            )
        ),
